// NCAAB (men's college basketball) canonical team table - ONE identity per D1 school (Kevin Oct 30 2026).
//
// Data: ncaab-teams.json (all 365 D1 teams, keyed by ESPN team id), generated by scripts/gen-ncaab-teams.js from
// live Kalshi / Polymarket US / Novig / ProphetX (relay) / Underdog / Odds API / sportsbook-futures names plus
// the manual ncaab-team-overrides.json. The SAME json + this file are vendored into aibetbuilder (lib/), so both
// repos resolve a venue's team name / code to the same ESPN id.
//
// resolveTeam(source, { code, name }, ctx)  -> { espnId, how } | { espnId: null, why, candidates? }
//   Exact only (code, then the source's own names, then any known name, then "<school> <mascot>"), never fuzzy.
//   A code or name that several schools share (e.g. Kalshi OAK = Oakland AND Oakwood, a non-D1 school) is NOT
//   guessed and NOT dropped: it is resolved with ctx = { opponentId | opponent: {code,name}, tipMs | date }
//   against the ESPN schedule (setSchedule) / the generator's learned Kalshi games. Unresolvable -> null.
// resolveGame(source, { away, home, tipMs | date })  -> { awayId, homeId, how } | { awayId: null, ... why }
// splitKalshiBlob(blob, { date })   'NDVILL' -> { codes: ['ND','VILL'], espnIds: [...] } | null
'use strict';

let DATA = require('./ncaab-teams.json');

const SOURCES = ['espn', 'kalshi', 'kalshiFutures', 'polymarket', 'polymarketFutures', 'novig', 'prophetx', 'underdog', 'oddsapi', 'books'];

const WORD = { saint: 'st', state: 'st', mt: 'mount', univ: 'university', intl: 'international', u: 'university' };
// "St. John's (NY)" / "Saint John's" -> "st johns ny"; Saint / State / St all collapse to "st" (both sides).
function normName(value) {
  return String(value || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/['\u2018\u2019\u02bb`.]/g, '').replace(/&/g, ' and ').replace(/[^a-z0-9]+/g, ' ').trim()
    .split(' ').filter((t) => t && t !== 'the').map((t) => WORD[t] || t).join(' ');
}
const normCode = (c) => String(c || '').trim().toUpperCase();

let IDX = null;
let SCHEDULE = []; // [{ homeId, awayId, ms }]

function espnKeys(t) {
  return [t.location, t.short, t.display, t.location && t.mascot ? `${t.location} ${t.mascot}` : ''].filter(Boolean);
}

function build(data) {
  const byId = new Map(); const names = new Map(); const mascots = new Map(); const src = {};
  const add = (m, k, id) => { if (!k) return; let s = m.get(k); if (!s) { s = new Set(); m.set(k, s); } s.add(id); };
  for (const t of data.teams || []) {
    const id = String(t.espnId); byId.set(id, t);
    for (const v of espnKeys(t)) add(names, normName(v), id);
    if (t.mascot) add(mascots, normName(t.mascot), id);
    for (const [s, a] of Object.entries(t.aliases || {})) {
      const x = src[s] || (src[s] = { codes: new Map(), names: new Map() });
      for (const c of a.codes || []) add(x.codes, normCode(c), id);
      for (const n of a.names || []) { add(x.names, normName(n), id); add(names, normName(n), id); }
    }
  }
  const ambiguous = {}; // source -> Map(CODE | norm name -> { d1:[ids], nonD1:[names] })
  for (const [s, m] of Object.entries((data.ambiguous) || {})) {
    ambiguous[s] = new Map(Object.entries(m).map(([k, v]) => [/^[A-Z0-9]+$/.test(k) ? k : normName(k), { d1: (v.d1 || []).map(String), nonD1: v.nonD1 || [] }]));
  }
  const nonD1 = {};
  for (const [s, list] of Object.entries(data.nonD1 || {})) nonD1[s] = new Set(list.map(normName));
  const kalshiGames = new Map(Object.entries(data.kalshiGames || {}));
  const kalshiCodes = [...new Set([...(src.kalshi ? src.kalshi.codes.keys() : []), ...(ambiguous.kalshi ? [...ambiguous.kalshi.keys()].filter((k) => /^[A-Z0-9]+$/.test(k)) : [])])]
    .sort((a, b) => b.length - a.length);
  return { byId, names, mascots, src, ambiguous, nonD1, kalshiGames, kalshiCodes };
}
const idx = () => IDX || (IDX = build(DATA));

function use(data) { DATA = data; IDX = null; }
// ESPN schedule context: [{ homeId, awayId, date | ms }] or an ESPN scoreboard body ({ events }).
function setSchedule(games) {
  const out = [];
  const list = games && Array.isArray(games.events) ? games.events : (games || []);
  for (const g of list) {
    if (g && g.competitions) {
      const c = g.competitions[0] || {}; const ids = (c.competitors || []).map((x) => String(x.id || (x.team && x.team.id) || ''));
      const h = (c.competitors || []).find((x) => x.homeAway === 'home'); const a = (c.competitors || []).find((x) => x.homeAway === 'away');
      if (ids.length === 2) out.push({ homeId: String((h && (h.id || (h.team && h.team.id))) || ids[0]), awayId: String((a && (a.id || (a.team && a.team.id))) || ids[1]), ms: Date.parse(c.date || g.date) });
    } else if (g && g.homeId && g.awayId) out.push({ homeId: String(g.homeId), awayId: String(g.awayId), ms: Number.isFinite(g.ms) ? g.ms : Date.parse(g.date) });
  }
  SCHEDULE = out.filter((g) => Number.isFinite(g.ms));
  return SCHEDULE.length;
}
// Merge more ESPN games into the schedule (deduped by teams + tip; keeps the last 5 days and everything ahead).
function addSchedule(games, nowMs = Date.now()) {
  const prev = SCHEDULE; setSchedule(games);
  const seen = new Map();
  for (const g of prev.concat(SCHEDULE)) if (g.ms >= nowMs - 5 * 864e5) seen.set(`${[g.homeId, g.awayId].sort().join('+')}|${g.ms}`, g);
  SCHEDULE = [...seen.values()];
  return SCHEDULE.length;
}

const etYmd = (ms) => new Intl.DateTimeFormat('en-CA', { timeZone: 'America/New_York', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date(ms));
// Does team `id` play `opponentId` (or anyone, when opponentId is null) near ctx.tipMs / on ctx.date (+-1 day)?
function opponentsNear(id, ctx) {
  const out = new Set();
  const tip = Number.isFinite(ctx.tipMs) ? ctx.tipMs : null;
  const day = ctx.date ? Date.parse(`${ctx.date}T17:00:00Z`) : null;
  for (const g of SCHEDULE) {
    if (g.homeId !== id && g.awayId !== id) continue;
    const near = tip != null ? Math.abs(g.ms - tip) <= 6 * 3600e3 : (day != null ? Math.abs(Date.parse(`${etYmd(g.ms)}T17:00:00Z`) - day) <= 864e5 : false);
    if (near) out.add(g.homeId === id ? g.awayId : g.homeId);
  }
  return out;
}

function lookupName(source, name) {
  const I = idx(); const n = normName(name);
  if (!n) return null;
  const own = I.src[source] && I.src[source].names.get(n);
  if (own) return own;
  const any = I.names.get(n);
  if (any) return any;
  // "<school> <mascot>" where <school> is a known name of the team that has that mascot
  const toks = n.split(' ');
  for (let k = 1; k < toks.length; k += 1) {
    const head = toks.slice(0, toks.length - k).join(' '); const tail = toks.slice(toks.length - k).join(' ');
    const byMascot = I.mascots.get(tail); if (!byMascot) continue;
    const byHead = (I.src[source] && I.src[source].names.get(head)) || I.names.get(head);
    if (!byHead) continue;
    const both = [...byHead].filter((id) => byMascot.has(id));
    if (both.length) return new Set(both);
  }
  return null;
}

function resolveTeam(source, { code, name } = {}, ctx = null) {
  const I = idx();
  let cands = null; const how = [];
  const amb = I.ambiguous[source] || new Map();
  let risky = null; // a code/name some NON-D1 school also uses
  if (code) {
    const c = normCode(code);
    const s = I.src[source] && I.src[source].codes.get(c);
    if (s) { cands = new Set(s); how.push('code'); }
    if (amb.has(c)) { const a = amb.get(c); cands = new Set([...(cands || []), ...a.d1]); if (a.nonD1.length) risky = a.nonD1; how.push('ambiguous_code'); }
  }
  if (name) {
    const s = lookupName(source, name);
    if (s) { cands = cands ? new Set([...cands].filter((id) => s.has(id))) : new Set(s); how.push('name'); risky = null; } else if ((I.nonD1[source] && I.nonD1[source].has(normName(name))) || (I.nonD1['*'] && I.nonD1['*'].has(normName(name)))) {
      return { espnId: null, why: 'non_d1' };
    } else if (code && cands && cands.size) {
      // code known but this name is not one of its D1 names: a non-D1 school using the same code
      if (risky || (amb.has(normCode(code)))) return { espnId: null, why: 'non_d1_or_unknown_name' };
    }
    const n = normName(name);
    if (amb.has(n)) { const a = amb.get(n); cands = new Set([...(cands || []), ...a.d1]); }
  }
  if (!cands || !cands.size) return { espnId: null, why: 'unknown' };
  if (cands.size === 1 && !risky) return { espnId: [...cands][0], how: how.join('+') };
  // several schools (or a non-D1 school) share this code / name: opponent + tip context from the ESPN schedule
  if (ctx) {
    let oppId = ctx.opponentId ? String(ctx.opponentId) : null;
    if (!oppId && ctx.opponent) { const o = resolveTeam(source, ctx.opponent); oppId = o.espnId; }
    const picks = [...cands].filter((id) => { const opp = opponentsNear(id, ctx); return oppId ? opp.has(oppId) : opp.size > 0; });
    if (picks.length === 1) {
      // the non-D1 namesake could be the one playing: only accept when the D1 pick really plays this opponent
      if (!risky || oppId) return { espnId: picks[0], how: `${how.join('+')}+context` };
    }
    if (oppId && picks.length === 0 && risky) return { espnId: null, why: 'non_d1_namesake' };
  }
  return { espnId: null, why: risky ? 'ambiguous_non_d1_namesake' : 'ambiguous', candidates: [...cands] };
}

function resolveGame(source, { away = {}, home = {}, tipMs = null, date = null } = {}) {
  const base = { tipMs, date };
  let a = resolveTeam(source, away); let h = resolveTeam(source, home);
  if (!a.espnId && a.why && /ambiguous/.test(a.why) && h.espnId) a = resolveTeam(source, away, { ...base, opponentId: h.espnId });
  if (!h.espnId && h.why && /ambiguous/.test(h.why) && a.espnId) h = resolveTeam(source, home, { ...base, opponentId: a.espnId });
  if (a.espnId && h.espnId && a.espnId !== h.espnId) return { awayId: a.espnId, homeId: h.espnId, how: `${a.how}|${h.how}` };
  return { awayId: a.espnId || null, homeId: h.espnId || null, why: `${a.espnId ? 'ok' : a.why}|${h.espnId ? 'ok' : h.why}` };
}

// Kalshi KXNCAAMB* team blob ('NDVILL', 'OAKMICH') -> the one reading with two known codes. Ambiguous codes are
// resolved against the learned Kalshi games / ESPN schedule for that date (opponent context), never guessed.
const MON = { JAN: '01', FEB: '02', MAR: '03', APR: '04', MAY: '05', JUN: '06', JUL: '07', AUG: '08', SEP: '09', OCT: '10', NOV: '11', DEC: '12' };
function kalshiDate(yymmmdd) { const m = /^(\d\d)([A-Z]{3})(\d\d)$/.exec(String(yymmmdd || '')); return m && MON[m[2]] ? `20${m[1]}-${MON[m[2]]}-${m[3]}` : null; }
const MON_BY_NUM = Object.fromEntries(Object.entries(MON).map(([k, v]) => [v, k]));
function splitKalshiBlob(blob, { date = null, dateBlob = null } = {}) {
  const I = idx(); const s = normCode(blob);
  if (!dateBlob && /^\d{4}-\d\d-\d\d$/.test(String(date || ''))) dateBlob = `${date.slice(2, 4)}${MON_BY_NUM[date.slice(5, 7)]}${date.slice(8, 10)}`;
  if (!date && dateBlob) date = kalshiDate(dateBlob);
  if (!/^[A-Z0-9]+$/.test(s)) return null;
  if (dateBlob && I.kalshiGames.has(`${dateBlob}${s}`)) {
    const learned = I.kalshiGames.get(`${dateBlob}${s}`);
    return learned && learned.codes ? { codes: learned.codes.slice(), espnIds: learned.espnIds.slice(), how: 'learned' } : null;
  }
  const out = [];
  for (const a of I.kalshiCodes) {
    if (!s.startsWith(a)) continue;
    const b = s.slice(a.length);
    if (b === a || !I.kalshiCodes.includes(b)) continue;
    const r = resolveGame('kalshi', { away: { code: a }, home: { code: b }, date });
    if (r.awayId && r.homeId) out.push({ codes: [a, b], espnIds: [r.awayId, r.homeId], how: r.how });
  }
  if (out.length > 1 && SCHEDULE.length && (date || dateBlob)) {
    // several readings: keep the one the ESPN schedule actually has on that date
    const d = date || kalshiDate(dateBlob);
    const real = out.filter((x) => opponentsNear(x.espnIds[0], { date: d }).has(x.espnIds[1]));
    return real.length === 1 ? { ...real[0], how: `${real[0].how}+schedule` } : null;
  }
  return out.length === 1 ? out[0] : null;
}

const team = (id) => idx().byId.get(String(id || '')) || null;
const teams = () => [...idx().byId.values()];
const aliasesOf = (id, source) => { const t = team(id); return (t && t.aliases && t.aliases[source]) || null; };
const codeFor = (id, source) => { const a = aliasesOf(id, source); return a && a.codes && a.codes.length ? a.codes[0] : null; };

module.exports = {
  SOURCES, normName, normCode, resolveTeam, resolveGame, splitKalshiBlob, kalshiDate, setSchedule, addSchedule, use, team, teams, aliasesOf, codeFor,
  get generatedAt() { return DATA.generatedAt || null; },
  get contentHash() { return DATA.contentHash || null; },
  get teamCount() { return (DATA.teams || []).length; },
};
